 "content": "def transform(grid):
    """Reconstruct a tiled binary motif and mark each occupied tile's coordinate."""
    n = len(grid)
    if not n or any(len(row) != n for row in grid):
        raise ValueError("expected a nonempty square grid")

    # The k-by-k motif tiles are separated by one-cell gutters:
    # n = k*k + (k-1).
    k = next((size for size in range(1, n + 1) if size * (size + 1) - 1 == n), None)
    if k is None:
        raise ValueError("grid dimensions do not match the tiled layout")
    pitch = k + 1

    # All visible symbols are copies of one k-by-k motif. Ignore 3-valued
    # masking cells and select the most frequently occurring nonempty motif.
    motifs = {}
    for tile_r in range(k):
        for tile_c in range(k):
            r0, c0 = tile_r * pitch, tile_c * pitch
            tile = tuple(tuple(2 if grid[r0 + r][c0 + c] == 2 else 0
                               for c in range(k)) for r in range(k))
            if any(value == 2 for row in tile for value in row):
                motifs[tile] = motifs.get(tile, 0) + 1
    if not motifs:
        raise ValueError("no visible motif found")
    motif = max(motifs, key=motifs.get)

    out = [[0] * n for _ in range(n)]
    for tile_r in range(k):
        for tile_c in range(k):
            if motif[tile_r][tile_c] != 2:
                continue
            r0, c0 = tile_r * pitch, tile_c * pitch
            for r in range(k):
                for c in range(k):
                    if motif[r][c] == 2:
                        out[r0 + r][c0 + c] = 2
            # Encode the tile's (row, column) on its copy of the motif.
            out[r0 + tile_r][c0 + tile_c] = 8
    return out
